SELECT

FROM support_request
WHERE deleted = 0

    AND request_no LIKE CONCAT('%', #{keyword}, '%')


    AND status = #{status}


    AND owner_org_id = #{ownerOrgId}

ORDER BY created_time DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM support_request
WHERE deleted = 0

    AND request_no LIKE CONCAT('%', #{keyword}, '%')


    AND status = #{status}


    AND owner_org_id = #{ownerOrgId}

SELECT

FROM support_request
WHERE deleted = 0

    AND support_dept_id = #{supportDeptId}


    AND status = #{status}


    AND assigned_emp_id = #{assignedEmpId}

ORDER BY created_time DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM support_request
WHERE deleted = 0

    AND support_dept_id = #{supportDeptId}


    AND status = #{status}


    AND assigned_emp_id = #{assignedEmpId}

SELECT COUNT(*) FROM support_request
WHERE cust_id = #{custId}
  AND product_id = #{productId}
  AND status IN ('IN_APPROVAL', 'IN_PROGRESS')
  AND deleted = 0

SELECT COUNT(*) FROM support_request
WHERE created_by = #{empId}
  AND status = 'COMPLETED'
  AND deleted = 0
  AND updated_time BETWEEN #{start} AND #{end}

SELECT COUNT(*) FROM support_request
WHERE assigned_emp_id = #{empId}
  AND status = 'COMPLETED'
  AND deleted = 0
  AND updated_time BETWEEN #{start} AND #{end}
